package com.taskflow.taskservice.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="tasks") public class Task { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long userId; @Column(nullable=false,length=160) private String title; @Column(length=2000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status=Status.PENDING; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Priority priority=Priority.MEDIUM; private LocalDate dueDate; @Column(nullable=false,updatable=false) private LocalDateTime createdAt; @Column(nullable=false) private LocalDateTime updatedAt;
@PrePersist void created(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void updated(){updatedAt=LocalDateTime.now();}
public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} public Priority getPriority(){return priority;} public void setPriority(Priority v){priority=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;}
public enum Status{PENDING,IN_PROGRESS,COMPLETED} public enum Priority{LOW,MEDIUM,HIGH} }
